package br.com.fastfps.chunk; import java.util.PriorityQueue; public final class ChunkUpdateQueue{private final PriorityQueue<ChunkUpdateTask>q=new PriorityQueue<ChunkUpdateTask>();public synchronized boolean offer(ChunkUpdateTask t,int limit){return q.size()<limit&&q.offer(t);}public synchronized ChunkUpdateTask poll(){return q.poll();}public synchronized int size(){return q.size();}public synchronized void clear(){q.clear();}}
